head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _3 : @spec3 중 fixedColumn(좌측 고정 컬럼 영역) 적용 + 분리 처리 전용. description 은 _1 과 동일, validation 은 분리 사유 1개만 보유.
scwin.tData = {
    "description" : "[gridView > P > mergeCol]<br/>동일값이 연속되는 Cell 이 자동으로 병합될때 대상이 되는 Body Column 의 ID 를 설정합니다.",
    "validation" : [
        "fixedColumn 속성으로 고정된 영역에도 적용되며 고정 영역은 분리되어 처리됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  ★ @spec3(fixedColumn) 전용 구성 : 좌측 고정 컬럼 영역(fixedColumn=2) + 스크롤 컬럼 영역 양쪽에서 mergeCol 필터가 적용되고
//     고정/스크롤 컬럼 영역이 분리되어 병합됨을 입증.
//    - fixedColumn=2 : 좌측 col1,col2 를 '고정 컬럼 영역'(_fixedColumnDiv) 으로 분리(가로 스크롤해도 좌측 고정).
//    - mergeCells="byrow" + mergeCellsFixedCols="byrow" 코드 고정 :
//        스크롤 컬럼 영역(mergeCells)·고정 컬럼 영역(mergeCellsFixedCols) 양쪽 모두 가로 병합 활성화.
//      (mergeCellsFixedCols 가 never 면 고정 컬럼 영역은 mergeCol 대상이어도 병합 안 됨 → 양쪽 동일 적용 필수)
//      ※ 엔진 _mergeByRow 는 스크롤(mergeCells)은 colStart=fixedColumn~colEnd, 고정(mergeCellsFixedCols/fixedCols)은 colStart=0~fixedColumn 으로
//        별도 2-pass 처리하므로, 같은 Row 에서 col1~col4 동일값이 이어져도 경계(col2↔col3)를 넘는 가로 병합이 생기지 않는다(=분리 처리).
//    - mergeCol="col1,col2,col3,col4" 코드 고정(전체 Body Column 대상). con 선택박스 없이 고정 데모.
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 병합 옵션 구성 (fixedColumn=2 + mergeCol/byrow 코드 고정)
    //  ★ mergeCol="col1,col2,col3,col4" 전체 컬럼 대상 + mergeCells/mergeCellsFixedCols="byrow" 코드 고정.
    //    fixedColumn=2 로 좌측 col1,col2 가 고정 컬럼 영역으로 분리되어, 같은 Row 동일값이 경계(col2↔col3)를 넘지 않고
    //    [고정 col1~col2] / [스크롤 col3~col4] 로 '각각 따로' 가로 병합됨(@spec3 분리 처리)을 보인다.
    let properties = {
        dataList: "data:dlt_bind",
        fixedColumn: 2,
        defaultCellHeight: 34,
        mergeCells: "byrow",                 // 스크롤(비고정) 컬럼 영역 가로 병합
        mergeCellsFixedCols: "byrow",        // 고정 컬럼 영역 가로 병합(동일 적용)
        mergeCol: "col1,col2,col3,col4",     // 전체 Body Column 병합 대상(코드 고정)
    };

    let cList = $c.gcm.createCList(properties);

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="mergeCells/mergeCellsFixedCols=byrow, mergeCol=col1,col2,col3,col4(전체, 코드 고정), fixedColumn=2(col1,col2 고정 컬럼 영역)"', '', 'label1');

    // dataList 생성 후 병합이 보이도록 데이터 구성
    //  ★ @spec3 분리 처리 검증의 핵심 : 같은 Row 의 값이 고정/스크롤 컬럼 경계(col2↔col3)를 넘어 이어져도
    //     가로 병합 그룹은 경계에서 끊겨 [고정 col1~col2] / [스크롤 col3~col4] '각각 따로' 병합되어야 한다.
    //
    //   행 | col1 | col2 | col3 | col4 |
    //   ---+======+======+------+------+   (== : 고정 컬럼 영역 col1,col2 / -- : 스크롤 col3,col4)
    //    0 |  S   |  S   |  S   |  S   |  → 4컬럼 동일값. byrow 시 고정 [col1~col2]=S / 스크롤 [col3~col4]=S 로 분리(경계 안넘음).
    //    1 |  T   |  T   |  U   |  U   |  → 고정 [col1~col2]=T / 스크롤 [col3~col4]=U (각 영역 독립 병합).
    //    2 |  V   |  W   |  X   |  X   |  → 고정 미병합(V≠W) / 스크롤 [col3~col4]=X.
    //    3 |  Y   |  Y   |  Y   |  Z   |  → 고정 [col1~col2]=Y / 스크롤 미병합(col3=Y 단독, col4=Z).
    //
    //  · 행0 이 핵심 : col1~col4 전부 'S' 라 경계가 없으면 [col1~col4] 단일 가로병합이 생겨야 하나,
    //    fixedColumn 분리 처리로 [고정 col1~col2] 와 [스크롤 col3~col4] 두 개로 끊겨야 함(분리 처리 O).
    //  · mergeCol=col1,col2,col3,col4(전체) 이므로 고정·스크롤 양 영역 모두 병합 대상 → 각 영역에서 독립적으로 가로 병합됨.
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "S", "col2": "S", "col3": "S", "col4": "S" },
        { "col1": "T", "col2": "T", "col3": "U", "col4": "U" },
        { "col1": "V", "col2": "W", "col3": "X", "col4": "X" },
        { "col1": "Y", "col2": "Y", "col3": "Y", "col4": "Z" }
    ], false);

    // target 생성
    //  ★ 컬럼 폭 합(360)을 그리드 폭(300)보다 크게 하여 가로 스크롤이 생기도록 함 → 좌측 고정(col1,col2)이 스크롤해도 남는 것을 확인.
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:300px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeCol sample"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column1" value="col1(고정)"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column2" value="col2(고정)"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column3" value="col3"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column4" value="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 고정영역 병합 확인 : 각 Body td 의 colSpan 을 읽어 가로 병합 그룹을 고정 컬럼 영역(col<fixedColumn)·스크롤 영역(col>=fixedColumn)으로 구분 출력.
//  ★ @spec3(fixedColumn) 검증 :
//     1) 고정 컬럼 영역에도 가로 병합이 적용되는지
//     2) 경계(fixedColumn)를 넘는 가로 병합 그룹이 없는지(고정/스크롤 분리 처리 O/X)
scwin.btn_checkMerge_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let fixedColumn = Number(target1.options.fixedColumn) || 0;
    bottom.setReturnValue("[옵션] mergeCells : " + target1.options.mergeCells + " / mergeCellsFixedCols : " + target1.options.mergeCellsFixedCols + " / mergeCol : " + target1.options.mergeCol + " / fixedColumn : " + target1.options.fixedColumn);

    // td id 는 그리드 id 기준(target1.id). e.target.id 는 클릭된 버튼 id 라 사용 불가
    let gid = target1.id;
    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_']");
    if (tds.length === 0) {
        bottom.setReturnValue("body cell td 를 찾을 수 없습니다.");
        return;
    }

    // colIndex → 컬럼 ID 매핑 (col1=0, col2=1, col3=2, col4=3)
    let colIdByIndex = ["col1", "col2", "col3", "col4"];

    let fixedDescs = [];   // 고정 컬럼 영역 가로 병합 그룹
    let scrollDescs = [];  // 스크롤 컬럼 영역 가로 병합 그룹
    let crossDescs = [];   // 경계를 넘는 가로 병합 그룹(있으면 분리 처리 위반)

    // 중복 td(고정 컬럼 컨테이너 _fixedColumnDiv 와 스크롤 컨테이너에 동일 id 복제) 방지용 :
    //  화면에 표시되는 td 만, (영역,행,열) 키로 1회만 처리
    let seen = {};

    for (let i = 0; i < tds.length; i++) {
        let td = tds[i];
        // 흡수되어 화면에 표시되지 않는 td 제외
        if (td.style.display === 'none' || getComputedStyle(td).display === 'none' || td.offsetParent === null) continue;
        let cs = td.colSpan || 1;
        if (cs <= 1) continue; // 가로 병합(colSpan>1)만 대상

        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        if (!m) continue;
        let r = Number(m[1]), c = Number(m[2]);
        let val = (td.textContent || "").trim();

        // 병합 앵커(좌측 시작 컬럼) 기준 영역 판정
        let region = (c < fixedColumn) ? "fixed" : "scroll";
        let key = region + "_" + r + "_" + c;
        if (seen[key]) continue;
        seen[key] = true;

        let lastCol = c + cs - 1;
        let desc = "행" + r + " [" + colIdByIndex[c] + "~" + colIdByIndex[lastCol] + "] = '" + val + "'";

        // 가로 병합이 고정/스크롤 컬럼 경계(fixedColumn)를 넘는지 판정
        if (fixedColumn > 0 && c < fixedColumn && lastCol >= fixedColumn) {
            crossDescs.push(desc);
        } else if (region === "fixed") {
            fixedDescs.push(desc);
        } else {
            scrollDescs.push(desc);
        }
    }

    bottom.setReturnValue("[고정 컬럼 영역(col<" + fixedColumn + ")] 가로병합 " + fixedDescs.length + "개");
    for (let d = 0; d < fixedDescs.length; d++) bottom.setReturnValue("  " + fixedDescs[d]);

    bottom.setReturnValue("[스크롤 컬럼 영역(col>=" + fixedColumn + ")] 가로병합 " + scrollDescs.length + "개");
    for (let d = 0; d < scrollDescs.length; d++) bottom.setReturnValue("  " + scrollDescs[d]);

    // @spec3 분리 처리 : 경계를 넘는 병합이 없어야 함(분리 처리 입증)
    if (crossDescs.length === 0) {
        bottom.setReturnValue("고정/스크롤 분리 처리 : O (경계 넘는 병합 없음)");
    } else {
        bottom.setReturnValue("고정/스크롤 분리 처리 : X (경계 넘는 병합 " + crossDescs.length + "개)");
        for (let d = 0; d < crossDescs.length; d++) bottom.setReturnValue("  (경계초과) " + crossDescs[d]);
    }
}
